// Clients posés sans entretien — V2 (brouillon). Lecture seule, aucune IA.
// Entrée : une page de /v1/events par item. Sortie : un seul item { ok, ... } lu par « Rédiger messages ».
const P = $('Parametres').first().json;
const now = DateTime.now().setZone('Europe/Paris');
const fr = d => d ? d.setZone('Europe/Paris').toFormat('dd/MM/yyyy') : '';
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
const rad = x => x * Math.PI / 180;
const km = (a, b) => { const h = Math.sin(rad(b.lat - a.lat) / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(rad(b.lon - a.lon) / 2) ** 2; return 12742 * Math.asin(Math.sqrt(h)); };
const coord = (lat, lon) => { const a = Number(lat), b = Number(lon); return (lat !== null && lat !== undefined && lat !== '' && isFinite(a) && isFinite(b) && (a !== 0 || b !== 0)) ? { lat: a, lon: b } : null; };

// ---------- 1. Contrôle d'intégrité : on n'envoie rien plutôt qu'une liste fausse ----------
const pages = $input.all().map(i => i.json || {});
const tailles = pages.map(p => Array.isArray(p.items) ? p.items.length : -1);
if (!pages.length || tailles.some(t => t < 0)) return [{ json: { ok: false, erreur: 'Réponse Interfast inattendue (pas de liste items). Rien n\'est envoyé.' } }];
if (tailles[tailles.length - 1] >= P.TAILLE_PAGE) return [{ json: { ok: false, erreur: 'Historique Interfast incomplet : ' + pages.length + ' pages lues, la dernière est pleine. Augmenter MAX_PAGES. Rien n\'est envoyé.' } }];

// ---------- 2. Classement d'une intervention ----------
// D'abord le TYPE Interfast (fiable), le titre seulement pour les types génériques (« Intervention », « Autre », vide...).
// Types vus le 20/10/2026 : Fin d'installation - PAC Air/Air|Air/Eau, Avancement de chantier, Entretien - Maintenance de PAC et climatisation,
// Dépannage, Visite avant devis (+ variantes), Devis, Intervention, Intervention - ClimatPro, Autre, Cerfa 15497, CR / PV de chantier.
const TYPES = [
  [/^fin d.installation/, 'pose'],
  [/^(avancement|compte rendu) de chantier|^pv de reception/, 'chantier'],
  [/^entretien|maintenance de pac/, 'entretien'],
  [/^depannage/, 'depannage'],
  [/^visite avant devis|^devis$/, 'devis']
];
const RX = {
  devis: /visite (technique|avant|devis|prealable)|\bmetre\b|chiffrage|estimation|(faire|etablir|pour) (un |le )?devis|^devis\b/,
  pose: /\binstall|\bpose\b|\bposer\b|mise en service|remplacement (de |d.)?(l.|la |le |une |un )?(unite|clim|climatisation|climatiseur|split|groupe|pac|pompe)/,
  entretien: /entretien|maintenance|nettoyage|revision|visite annuelle|controle annuel|visite (de )?contrat/,
  depannage: /depannage|\bpanne\b|fuite|\berreur\b|code (defaut|erreur)|ne fonctionne|ne fait plus|ne (re)?demarre|\bsav\b|diagnostic|recharge/
};
const cats = s => {
  s = norm(s).replace(/\b(suite|selon|cf|voir|ref)?\.?\s*devis\s*(n\S*\s*)?d[ce]\s?\d{3,6}\b/g, ' ');   // « suite devis DC1234 » n'est pas une visite devis
  const c = new Set(Object.keys(RX).filter(k => RX[k].test(s)));
  if (/\bdepose\b/.test(s) && !/\brepose\b/.test(s)) { c.delete('pose'); c.add('depose'); }
  if (/\brepose\b/.test(s)) c.add('repose');
  return c;
};
function classer(ev) {
  const CTi = cats(ev.title);
  const depose = CTi.has('depose');
  if (ev.maintenance) return { k: 'entretien', contrat: true, depose };
  const t = norm(ev.type);
  const parType = (TYPES.find(([rx]) => rx.test(t)) || [])[1];
  if (parType) {
    // Type net : il fait foi. Un titre qui parle d'autre chose (pose / entretien / remise en service) est noté.
    const autres = ['pose', 'entretien'].filter(x => CTi.has(x) && x !== parType && !(parType === 'chantier' && x === 'pose'));
    return autres.length ? { k: parType, conflit: parType + ' + ' + autres.join(' + '), depose } : { k: parType, depose };
  }
  const utiles = ['pose', 'entretien', 'depannage'].filter(x => CTi.has(x));
  if (!utiles.length) {
    if (CTi.has('repose')) return { k: 'ambigu', conflit: 'repose', depose };
    return { k: CTi.has('devis') ? 'devis' : (depose ? 'depose' : 'autre'), depose };
  }
  if (utiles.length === 1) return { k: utiles[0], parTitre: true, depose };
  return { k: 'ambigu', conflit: utiles.join(' + '), depose };
}

// ---------- 3. Lecture des interventions, regroupées par client puis par site ----------
const exclure = new RegExp(P.EXCLURE_CLIENTS, 'i');
const vus = new Set();
const C = {};
const futurs = [];
const libellesInconnus = {};
let nbEv = 0;
const finRoute = now.plus({ days: P.JOURS_ROUTE }).endOf('day');
for (const p of pages) for (const ev of p.items) {
  if (!ev || vus.has(String(ev.id))) continue;
  vus.add(String(ev.id));
  if (ev.lifecycleState === 'cancelled' || ev.category === 'task' || ev.category === 'absence' || !ev.client || !ev.client.id) continue;
  const d = DateTime.fromISO(String(ev.start || ''), { zone: 'utc' });
  if (!d.isValid) continue;
  nbEv++;
  const id = String(ev.client.id);
  const nom = String(ev.client.name || '').trim();
  const pos = coord(ev.lat, ev.lon);
  const cl = classer(ev);
  if (cl.k === 'autre') { const l = (norm(ev.type) || '(sans type)') + ' : ' + norm(ev.title).slice(0, 35); libellesInconnus[l] = (libellesInconnus[l] || 0) + 1; }
  if (d > now && d <= finRoute && cl.k !== 'devis') futurs.push({ ev, d, pos, clientId: id, nom });
  if (exclure.test(nom)) continue;
  const c = C[id] || (C[id] = { id, nom, sites: [], contratRecent: false, contratAncien: null });
  if (cl.contrat) {
    if (d > now.minus({ months: P.CONTRAT_MOIS })) c.contratRecent = true;
    else if (!c.contratAncien || d > c.contratAncien) c.contratAncien = d;
  }
  // Site : même adresse normalisée, ou à moins de MEME_SITE_KM
  const adr = String(ev.address || '').trim();
  const cleAdr = norm(adr).replace(/[^a-z0-9]/g, '');
  let s = c.sites.find(x => (cleAdr && x.cleAdr === cleAdr) || (pos && x.pos && km(pos, x.pos) <= P.MEME_SITE_KM));
  if (!s) { s = { adr, cleAdr, pos, ev: [] }; c.sites.push(s); }
  if (!s.pos && pos) s.pos = pos;
  if (!s.adr && adr) { s.adr = adr; s.cleAdr = cleAdr; }
  s.ev.push({ d, cl, ev, fini: !!ev.finished });
}

// ---------- 4. Règles de détection par site ----------
// Référence = la PREMIÈRE pose qui n'a été suivie d'aucun entretien net. « Jamais entretenu depuis le JJ/MM/AAAA ».
// Entretien net = clôturé, libellé sans ambiguïté, et pas collé à une pose (sinon on ne sait pas quelle clim a été entretenue).
const liste = [], aVerifier = [];
const stats = { interventions: nbEv, pages: pages.length, clients: Object.keys(C).length, sousContrat: 0, entretienPrevu: 0, entretenus: 0, poseRecente: 0 };
const ville = a => { const m = String(a || '').match(/(\d{5})[\s,]+([^,]+)$/); return m ? m[2].trim() : ''; };
const objet = ev => [ev.type, ev.title && ev.title !== ev.type ? ev.title : ''].filter(Boolean).join(' : ').replace(/\s+/g, ' ').slice(0, 90);
const limiteNC = now.minus({ days: P.NON_CLOTURE_JOURS });
const ligne = (c, s, ref, extra) => Object.assign({ client_id: c.id, nom: c.nom, site: s.adr, ville: ville(s.adr), pos: s.pos,
  pose_le: ref.d, pose_objet: objet(ref.ev), mois: Math.floor(now.diff(ref.d, 'months').months), multiSites: c.sites.length > 1 }, extra || {});
for (const c of Object.values(C)) {
  for (const s of c.sites) {
    const passe = s.ev.filter(e => e.d <= now).sort((a, b) => a.d - b.d);
    const poses = passe.filter(e => e.cl.k === 'pose');
    if (!poses.length) {
      // Pas de pose nette : libellé ambigu (repose, pose + dépannage...) ou chantier sans « Fin d'installation » → on signale
      if (c.contratRecent) continue;
      const amb = passe.filter(e => (e.cl.k === 'ambigu' && /pose/.test(e.cl.conflit)) || (e.cl.k === 'chantier' && e.d < now.minus({ months: P.MOIS_MIN }))).pop();
      if (!amb || passe.some(e => e.cl.k === 'entretien' && e.fini && e.d > amb.d) || s.ev.some(e => e.cl.k === 'entretien' && e.d > now)) continue;
      if (Math.floor(now.diff(amb.d, 'months').months) < P.MOIS_MIN) continue;
      const r = amb.cl.k === 'chantier' ? 'chantier du ' + fr(amb.d) + ' sans « Fin d\'installation » dans Interfast'
        : amb.cl.conflit === 'repose' ? 'repose du ' + fr(amb.d) + ' : réinstallation par ClimatPro, à compter comme une pose ?'
        : 'libellé ambigu ' + amb.cl.conflit + ' le ' + fr(amb.d);
      aVerifier.push(ligne(c, s, amb, { raisons: [r + ' (« ' + objet(amb.ev) + ' »)'] }));
      continue;
    }
    const prochePose = e => poses.some(p => Math.abs(e.d.diff(p.d, 'days').days) <= P.ENTRETIEN_PROCHE_JOURS);
    const ents = passe.filter(e => e.cl.k === 'entretien' && e.fini);
    const nets = ents.filter(e => !e.cl.conflit && !prochePose(e));
    const dernierNet = nets.length ? nets[nets.length - 1].d : null;
    const posesApres = poses.filter(p => !dernierNet || p.d > dernierNet);
    if (c.contratRecent) { stats.sousContrat++; continue; }
    if (!posesApres.length) { stats.entretenus++; continue; }
    const ref = posesApres[0];
    if (s.ev.some(e => e.cl.k === 'entretien' && e.d > now)) { stats.entretienPrevu++; continue; }
    const mois = Math.floor(now.diff(ref.d, 'months').months);
    if (mois < P.MOIS_MIN) { stats.poseRecente++; continue; }
    const apres = passe.filter(e => e.d >= ref.d && e !== ref);
    const raisons = [];
    for (const p of posesApres.filter(p => !p.fini && p.d < limiteNC)) raisons.push('pose du ' + fr(p.d) + ' jamais clôturée dans Interfast');
    if (ref.cl.conflit) raisons.push('libellé de la pose mélange ' + ref.cl.conflit + ' (« ' + objet(ref.ev) + ' »)');
    for (const e of ents.filter(e => e.d >= ref.d && !nets.includes(e))) raisons.push('entretien du ' + fr(e.d) + (prochePose(e) ? ' collé à une pose' : ' au libellé ambigu') + ' : sur la clim posée ou une autre ? (« ' + objet(e.ev) + ' »)');
    for (const e of apres.filter(e => e.cl.k === 'entretien' && !e.fini && e.d < limiteNC)) raisons.push('entretien du ' + fr(e.d) + ' non clôturé : fait ou pas ?');
    for (const e of apres.filter(e => e.cl.k === 'ambigu' || (e.cl.k === 'depannage' && e.cl.conflit))) raisons.push('intervention du ' + fr(e.d) + ' : ' + e.cl.conflit + ' (« ' + objet(e.ev) + ' »)');
    for (const e of apres.filter(e => e.cl.depose)) raisons.push('dépose le ' + fr(e.d) + ' après la pose : clim encore en place ?');
    if (c.contratAncien) raisons.push('ancien contrat d\'entretien (dernière visite contrat le ' + fr(c.contratAncien) + ') : résilié ?');
    if (!s.adr && c.sites.length > 1) raisons.push('client à plusieurs adresses, pose sans adresse');
    if (ref.cl.parTitre && !/install|pose/.test(norm(ref.ev.title))) raisons.push('pose déduite d\'un libellé indirect (« ' + objet(ref.ev) + ' »)');
    const extra = { depannages: apres.filter(e => e.cl.k === 'depannage').length,
      autrePose: posesApres.length > 1 ? fr(posesApres[posesApres.length - 1].d) : '', dejaEntretenuAvant: dernierNet ? fr(dernierNet) : '' };
    if (raisons.length) aVerifier.push(ligne(c, s, ref, Object.assign(extra, { raisons }))); else liste.push(ligne(c, s, ref, extra));
  }
}

// ---------- 5. Bonus : sur la route d'une intervention prévue ----------
const gps = {};
for (const it of $('Lire clients_gps').all()) { const r = it.json || {}; const p = coord(r.lat, r.lon); if (r.client_id && p) gps[String(r.client_id)] = p; }
const techs = ev => [...new Set((ev.users || []).map(u => (u && (u.firstName || u.name || u.lastName)) || P.NOMS_TECH[u && u.id] || ('tech ' + (u && u.id))))].join(' + ') || 'non attribué';
const route = [];
for (const x of liste.concat(aVerifier)) {
  const p = x.pos || gps[x.client_id];
  if (!p) continue;
  let best = null;
  for (const f of futurs) {
    if (f.clientId === x.client_id) continue;
    const fp = f.pos || gps[f.clientId];
    if (!fp) continue;
    const dist = km(p, fp);
    if (dist <= P.RAYON_KM && (!best || f.d < best.f.d || (+f.d === +best.f.d && dist < best.dist))) best = { f, dist };
  }
  if (best) route.push({ x, f: best.f, dist: Math.round(best.dist * 10) / 10 });
}
route.sort((a, b) => a.f.d - b.f.d || a.dist - b.dist);

const enLigne = x => Object.assign({}, x, { pose_le: fr(x.pose_le), pos: undefined });
return [{ json: {
  ok: true, maj: now.toISO(), stats,
  liste: liste.sort((a, b) => b.mois - a.mois).map(enLigne),
  aVerifier: aVerifier.sort((a, b) => b.mois - a.mois).map(enLigne),
  route: route.map(r => ({ client_id: r.x.client_id, nom: r.x.nom, ville: r.x.ville, mois: r.x.mois, aVerifier: !!r.x.raisons,
    quand: r.f.d.setZone('Europe/Paris').setLocale('fr').toFormat('ccc dd/MM'), qui: techs(r.f.ev), chez: r.f.nom, chezVille: ville(r.f.ev.address), km: r.dist })),
  libellesInconnus: Object.entries(libellesInconnus).sort((a, b) => b[1] - a[1]).slice(0, 10)
} }];

// Construit les messages Telegram (HTML échappé par le node d'envoi) pour chaque admin actif de bot_users.
const P = $('Parametres').first().json;
const r = $input.first().json;
const admins = $('Lire utilisateurs').all().map(i => i.json).filter(u => u && u.actif && u.role === 'admin' && u.telegram_id);
if (!admins.length) return [];
const blocs = [];
if (!r.ok) {
  blocs.push('⚠️ Clients posés sans entretien : rapport non envoyé.\n' + r.erreur);
} else {
  const s = r.stats;
  blocs.push('🔧 Clients posés sans entretien (pose ≥ ' + P.MOIS_MIN + ' mois, hors contrat)\n'
    + r.liste.length + ' à proposer, ' + r.aVerifier.length + ' à vérifier.\n'
    + 'Écartés : ' + s.sousContrat + ' sous contrat, ' + s.entretienPrevu + ' entretien déjà planifié, ' + s.entretenus + ' déjà entretenus, ' + s.poseRecente + ' posés depuis moins de ' + P.MOIS_MIN + ' mois.\n'
    + 'Base : ' + s.interventions + ' interventions Interfast (' + s.pages + ' pages), historique depuis l\'arrivée d\'Interfast seulement.');
  if (r.route.length) {
    // Regroupé par intervention prévue : « mar. 21/10 — Christophe chez X (Cannes) » puis les clients à proposer autour
    const g = {};
    for (const x of r.route) { const k = x.quand + ' — ' + x.qui + ' chez ' + x.chez + (x.chezVille ? ' (' + x.chezVille + ')' : ''); (g[k] = g[k] || []).push(x); }
    blocs.push('🚐 Sur la route (≤ ' + String(P.RAYON_KM).replace('.', ',') + ' km d\'une intervention prévue dans les ' + P.JOURS_ROUTE + ' jours)\n'
      + Object.entries(g).map(([k, xs]) => k + '\n' + xs.map(x => '   → ' + x.nom + ' à ' + String(x.km).replace('.', ',') + ' km, ' + x.mois + ' mois sans entretien' + (x.aVerifier ? ' [à vérifier]' : '') + ' · id ' + x.client_id).join('\n')).join('\n'));
  } else blocs.push('🚐 Sur la route : aucun client concerné à moins de ' + String(P.RAYON_KM).replace('.', ',') + ' km des interventions des ' + P.JOURS_ROUTE + ' prochains jours.');
  const parVille = {};
  for (const x of r.liste.slice(0, P.MAX_LIGNES)) (parVille[x.ville || 'Ville inconnue'] = parVille[x.ville || 'Ville inconnue'] || []).push(x);
  const villes = Object.keys(parVille).sort((a, b) => parVille[b].length - parVille[a].length);
  for (const v of villes) blocs.push('📍 ' + v + ' (' + parVille[v].length + ')\n' + parVille[v].map(x => '• ' + x.nom + ' — posé le ' + x.pose_le + ' (' + x.mois + ' mois) : ' + x.pose_objet + (x.depannages ? ' · ' + x.depannages + ' dépannage(s) depuis' : '') + (x.autrePose ? ' · autre pose le ' + x.autrePose : '') + (x.dejaEntretenuAvant ? ' · entretien avant cette pose le ' + x.dejaEntretenuAvant : '') + ' · id ' + x.client_id).join('\n'));
  if (r.liste.length > P.MAX_LIGNES) blocs.push('… et ' + (r.liste.length - P.MAX_LIGNES) + ' autres (les plus anciens sont affichés en premier).');
  if (r.aVerifier.length) blocs.push('❓ À vérifier avant de proposer (' + r.aVerifier.length + ')\n' + r.aVerifier.slice(0, 40).map(x => '• ' + x.nom + (x.ville ? ' (' + x.ville + ')' : '') + ' — ' + x.raisons.join(' ; ') + ' · id ' + x.client_id).join('\n') + (r.aVerifier.length > 40 ? '\n… et ' + (r.aVerifier.length - 40) + ' autres.' : ''));
  if (r.libellesInconnus.length) blocs.push('🏷️ Libellés non reconnus (ni pose, ni entretien, ni dépannage), pour régler les règles :\n' + r.libellesInconnus.map(([l, n]) => '• « ' + l + ' » × ' + n).join('\n'));
}
// Découpe en messages de 3 900 caractères maximum, sans couper une ligne
const msgs = [];
let cur = '';
for (const b of blocs) for (const ligne of (b + '\n').split('\n')) {
  const l = ligne.length > 3800 ? ligne.slice(0, 3800) + '…' : ligne;
  if (cur.length + l.length + 1 > 3900) { msgs.push(cur.trim()); cur = ''; }
  cur += l + '\n';
}
if (cur.trim()) msgs.push(cur.trim());
const out = [];
for (const a of admins) for (const t of msgs) out.push({ json: { chat_id: String(a.telegram_id), text: t } });
return out;

// Interfast en erreur : on prévient les admins au lieu d'envoyer une liste fausse.
const admins = $('Lire utilisateurs').all().map(i => i.json).filter(u => u && u.actif && u.role === 'admin' && u.telegram_id);
const e = $input.first().json || {};
const msg = String((e.error && (e.error.message || e.error)) || e.message || 'erreur inconnue').slice(0, 300);
return admins.map(a => ({ json: { chat_id: String(a.telegram_id), text: '⚠️ Clients posés sans entretien : lecture Interfast impossible, rapport non envoyé.\n' + msg } }));
